<template><view class="account-page feature-page"><FeaturePageState :status="status" :error="error" @retry="load"/><template v-if="status==='ready'"><text class="feature-note">{{context.label}}</text><text v-if="kind==='entitlement'&&entitlementStatusText" class="feature-note">{{entitlementStatusText}}</text><view v-if="options.balances?.length" class="business-metrics"><view v-for="metric in options.balances" :key="metric.label" class="business-metric"><text>{{metric.label}}</text><view>{{format(metric)}}</view></view></view><view v-if="!result" class="business-operation-form"><view v-for="field in options.fields" :key="field.key" class="business-operation-field"><text>{{field.label}}</text><picker v-if="field.type==='enum'" :range="choices(field)" range-key="label" :value="choiceIndex(field)" :disabled="busy" @change="setValue(field.key,choices(field)[$event.detail.value]?.value)"><view class="business-enum-value">{{choices(field).find(item=>item.value===draft[field.key])?.label||'请选择'}}</view></picker><input v-else :value="draft[field.key]||''" type="digit" :maxlength="field.type==='money'?15:4" :disabled="busy" placeholder="请输入" @input="setValue(field.key,$event.detail.value)"/></view><text v-if="operationError" class="business-operation-error">{{operationError}}</text><button class="primary" :disabled="busy||!options.allowedActions?.includes('quote')" @click="preview">{{busy?'处理中…':'生成预览'}}</button><text v-if="!options.allowedActions?.includes('quote')" class="feature-note">{{options.disabledReason||'此操作暂未开放'}}</text></view><view v-if="quote&&!result" class="business-operation-result"><view class="business-record-title">请确认本次操作</view><view v-for="detail in quote.details" :key="detail.label" class="business-row"><text>{{detail.label}}</text><text>{{format(detail)}}</text></view><button class="primary" :disabled="busy||!options.allowedActions?.includes('submit')" @click="commit">{{busy?'提交中…':'确认提交'}}</button></view><view v-if="result" class="business-operation-result"><view class="business-record-title">{{successTitle}}</view><view>{{statusLabel(result.status)}}</view><text class="feature-note">{{result.status==='PENDING_PAYMENT'||result.status==='CREATED'?'订单未支付，名额和权益未增加。':result.status==='PENDING_REVIEW'?'等待审核，不代表已打款。':result.status==='PENDING_SETTLEMENT'?'等待后台结算，未增加可提现金额。':'结果以所属身份的后台记录为准。'}}</text><button v-if="isCommitAwaitingPayment(result)" class="primary" @click="payOrder">去支付</button><button class="secondary" @click="back">返回上一页</button><button v-if="kind==='withdraw'" class="business-link" @click="records">查看提现记录</button></view></template></view></template>
<script setup>
import {ref,computed,watch,onUnmounted} from 'vue'
import {config} from '../config'
import {money,percent} from '../features/exclusive/format'
import {getCommerceOrder} from '../services/commerce'
import {getBusinessContext} from '../services/business'
import {getBusinessOperationOptions,previewBusinessOperation,commitBusinessOperation,commitPaymentRef,isCommitAwaitingPayment} from '../services/business-operations'
import {entitlementDisplayState,entitlementExpiry,isEntitlementCurrentlyValid,invalidateEntitlementViews} from '../services/api'
import {useAsyncPage} from '../composables/useAsyncPage'
import FeaturePageState from './FeaturePageState.vue'
const props=defineProps({kind:String,pageQuery:Object}),context=ref(null),draft=ref({}),quote=ref(null),result=ref(null),busy=ref(false),operationError=ref(''),isMock=config.useMock
let active=true,epoch=0,attemptKey='',receivedAt=0
const {data:options,status,error,load}=useAsyncPage(async()=>{const ctx=await getBusinessContext(['withdraw','allocation'].includes(props.kind)?null:'wholesale',props.pageQuery?.contextId);const output=await getBusinessOperationOptions(props.kind,ctx.id,props.pageQuery?.entryId||'');if(!Array.isArray(output?.fields)||!Array.isArray(output.allowedActions)||output.fields.some(field=>!['enum','integer','money'].includes(field.type)))throw new Error('操作信息暂时无法加载，请稍后重试');context.value=ctx;const next={};for(const field of output.fields){if(field.type==='enum')next[field.key]=field.options?.some(item=>item.value===props.pageQuery?.[field.key])?props.pageQuery[field.key]:'';else next[field.key]=''}draft.value=next;quote.value=null;result.value=null;attemptKey='';return output},false)
watch(()=>props.pageQuery,query=>{if(query)load()},{immediate:true})
const format=detail=>detail.kind==='money'?`${money(detail.value)}积分`:detail.kind==='percent'?percent(detail.value):detail.value??0
function formatExpiry(value){if(value==null||value==='')return '';const time=typeof value==='number'?value:typeof value==='string'&&/^\d+$/.test(value.trim())?Number(value):Date.parse(value);if(!Number.isFinite(time))return String(value).slice(0,10);const date=new Date(time),pad=n=>String(n).padStart(2,'0');return `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}`}
const entitlementStatusText=computed(()=>{if(props.kind!=='entitlement')return '';const opts=options.value||{};const state=entitlementDisplayState(opts.entitlement,{currentPaid:opts.currentPaid,currentExpiresAt:opts.currentExpiresAt});const until=entitlementExpiry(opts.entitlement,{currentExpiresAt:opts.currentExpiresAt});if(state==='never_paid')return '您暂未开通权益收益费';if(state==='expired')return until?`已过期（权益到期：${formatExpiry(until)}）`:'已过期';if(state==='active'&&until)return `权益到期：${formatExpiry(until)}`;return ''})
function choices(field){return (field.options||[]).filter(item=>!item.accountType||item.accountType===draft.value.accountType)}
function choiceIndex(field){return Math.max(0,choices(field).findIndex(item=>item.value===draft.value[field.key]))}
function setValue(key,value){if(busy.value)return;draft.value[key]=value;if(key==='accountType')draft.value.payeeToken='';quote.value=null;attemptKey='';operationError.value='';++epoch}
async function preview(){if(busy.value)return;const current=epoch;busy.value=true;operationError.value='';quote.value=null;attemptKey='';try{const output=await previewBusinessOperation(props.kind,context.value.id,draft.value,props.pageQuery?.entryId||'');if(active&&current===epoch){quote.value=output;receivedAt=Date.now()}}catch(reason){if(active&&current===epoch)operationError.value=reason.message||'预览失败'}finally{if(active)busy.value=false}}
async function syncEntitlementAfterPayment(base,current,prefetched){if(props.kind!=='entitlement')return base;invalidateEntitlementViews();const latest=prefetched||await getBusinessOperationOptions(props.kind,context.value.id,props.pageQuery?.entryId||'');if(!active||current!==epoch)return base;options.value=latest;const ent=latest?.entitlement||base?.entitlement;const extras={currentPaid:latest?.currentPaid??base?.currentPaid,currentExpiresAt:latest?.currentExpiresAt};const activeNow=isEntitlementCurrentlyValid(ent,extras);const next={...base,entitlement:ent,validUntil:base.validUntil??entitlementExpiry(ent,extras),entitlementActive:activeNow};result.value=next;return next}
async function commit(){if(busy.value||!quote.value)return;if(quote.value.expiresAt<=quote.value.serverTime+Date.now()-receivedAt){operationError.value='预览已失效，请重新确认';quote.value=null;return}const current=epoch;busy.value=true;operationError.value='';if(!attemptKey)attemptKey=`business-${Date.now()}-${Math.random().toString(36).slice(2)}`;try{const output=await commitBusinessOperation(props.kind,context.value.id,quote.value.id,attemptKey,props.pageQuery?.entryId||'');if(active&&current===epoch){result.value=output;options.value={...options.value,balances:Array.isArray(output.balances)?output.balances:[],...(output.entitlement?{entitlement:output.entitlement}:{})};quote.value=null;if(props.kind==='entitlement'&&!isCommitAwaitingPayment(output))await syncEntitlementAfterPayment(output,current)}}catch(reason){if(active&&current===epoch)operationError.value=reason.message||'提交未完成，请稍后查看记录'}finally{if(active)busy.value=false}}
const statusLabel=status=>({PENDING_PAYMENT:'待支付',CREATED:'待支付',PENDING_REVIEW:'待审核',PENDING_SETTLEMENT:'待结算',DEMO_APPLIED:'已处理',PAID:'已支付',CANCELLED:'已取消'}[status]||'处理结果待确认')
const successLabels={'quota-transfer':'划拨名额成功',upgrade:'设置等级成功','bind-store':'绑定门店成功','quota-purchase':'购买VIP名额成功',withdraw:'提现申请成功',entitlement:'年度权益开通成功',allocation:'积分分配成功'}
const successTitle=computed(()=>{const status=result.value?.status;if(status==='PENDING_PAYMENT'||status==='CREATED')return '订单待支付';if(status==='PENDING_REVIEW')return '提现申请已提交，等待审核';if(props.kind==='entitlement'){if(result.value?.entitlementActive===true)return '年度权益开通成功';if(['PAID','SUCCEEDED','COMPLETED'].includes(status))return '支付已完成';return '操作已完成'}if(status==='PAID')return successLabels[props.kind]||'支付成功';return successLabels[props.kind]||'操作已完成'})
function payOrder(){const id=commitPaymentRef(result.value);if(!id)return;uni.navigateTo({url:`/pages/payment/cashier?orderId=${encodeURIComponent(id)}`})}
function back(){if(getCurrentPages().length>1)uni.navigateBack();else uni.switchTab({url:'/pages/partners/index'})}
function records(){uni.navigateTo({url:`/pages/wallet/withdrawals?contextId=${encodeURIComponent(context.value.id)}`})}
async function refresh(){if(busy.value)return;const paymentRef=commitPaymentRef(result.value);if((result.value?.status==='PENDING_PAYMENT'||result.value?.status==='CREATED')&&paymentRef){try{const orderId=paymentRef,current=epoch;const response=await getCommerceOrder(orderId);if(props.kind==='entitlement')invalidateEntitlementViews();const latest=await getBusinessOperationOptions(props.kind,context.value.id,props.pageQuery?.entryId||'');if(active&&current===epoch&&commitPaymentRef(result.value)===orderId){options.value=latest;if(['COMPLETED','PAID'].includes(response.order.status)){if(props.kind==='entitlement')await syncEntitlementAfterPayment({...result.value,status:'PAID',validUntil:result.value.validUntil},current,latest);else result.value={...result.value,status:'PAID'}}else if(response.order.status==='CANCELLED')result.value={...result.value,status:'CANCELLED'}}}catch(e){if(active)operationError.value=e.message}return}if(!quote.value&&!result.value)return load()}
onUnmounted(()=>{active=false;++epoch});defineExpose({refresh})
</script>
<style>@import '../styles/account.css';@import '../styles/exclusive.css';@import '../styles/business.css';</style>
